await db.runTransaction(async (transaction) => {
  const pipeline = db.pipeline()
    .collection("users")
    .distinct(field("name"))
    .insert({
      collection: "new_users",
      documentIdExpression: stringConcat(constant("new_"), field("name"))
    });

  await transaction.execute(pipeline);
});
